/*
 * 蜻蜓FM (app.qtfm.cn) 原生 Ceru v2 插件
 * 站点：https://app.qtfm.cn（App BFF）/ https://audio.qingting.fm（Web 302 兜底）
 * 音质：128k(HD MP3) / 64k(SD M4A) / 24k(Low M4A)
 *
 * 实测（2026-11-19）：
 *   搜索: GET /m-bff/v1/search/result?k={kw}&sort_type=0&page={p}&include=program_ondemand
 *          &pagesize=30&k_src=direct → errorno=0, data.data[]（type='program'）
 *          条目带深链接 qingtingfm://app.qingting.fm/playingview?type=ondemand&channel_id=&program_id=
 *          仅 type==='program' 为可播曲目（其余 type 过滤掉）
 *   取链: GET /m-bff/v1/audiostreams/channel/{ch}/program/{pg}?access_token=&device_id=...&type=play
 *          &sign=HMAC-MD5(key=99@b8#571(bb38_b), path_query)
 *          → errorno=0, data.editions[]（{fmt,bitrate,sizeKB,urls[]}）
 *   档位链（宁低勿高）: 128k=[mp3-128,m4a-62,m4a-22] 64k=[m4a-62,mp3-128,m4a-22] 24k=[m4a-22,m4a-62,mp3-128]
 *   校验: Range 0-1023 魔数（mp3=ID3/0xFFEx, m4a=offset4 ftyp）+ content-range 与 editions.size*1024 偏差 ±10%
 *   兜底: App API 失败/全档挂 → Web /audiostream/redirect/{ch}/{pg}?t=ms&sign=HMAC-MD5(Web key) 302
 *          浏览器风格头（App 头 403）；直链 host 白名单 *.qtfm.cn/*.tliveapp.com/*.qingting.fm
 *   歌词: 无（有声书/播客/电台直播内容）
 */
exports.manifest = {
  manifestVersion: 2,
  id: 'ceru.qingting',
  name: '蜻蜓FM',
  version: '1.0.0',
  description: '支持音质：128k/64k/24k',
  author: 'hebijunge',
  engines: { hostApi: '^2.0.0', logicRuntime: 'ceru-js@1' },
  modules: { logic: { entry: 'logic.main' } },
  permissions: [{ key: 'network', name: 'network.request', reason: '搜索与取链需要访问网络' }],
  contributes: {
    providers: [{
      id: "ceru.qingting",
      name: '蜻蜓FM',
      protocols: ['music.search@1', 'music.resolve@1'],
      qualities: ['128k', '64k', '24k'],
      connectionMode: 'none'
    }]
  }
};

